<?php
namespace Database\Seeders;
use Illuminate\Database\Seeder; use App\Models\{User,Project,ProjectPhase,Company,Contract,ContractSite};
class DatabaseSeeder extends Seeder { public function run():void {$prise=Project::create(['code'=>'PRISE','name'=>'Projet de Renforcement des Infrastructures Socio-Economique dans Zone Centre de la RDC']);$predire=Project::create(['code'=>'PREDIRE','name'=>"Programme d'appui au développement des infrastructures et de valorisation des ressources en eau transfrontalières entre la RCA et RDC"]);ProjectPhase::create(['project_id'=>$prise->id,'number'=>1,'name'=>'Phase 1','is_archived'=>true]);ProjectPhase::create(['project_id'=>$prise->id,'number'=>2,'name'=>'Phase 2','is_current'=>true]);ProjectPhase::create(['project_id'=>$predire->id,'number'=>1,'name'=>'Phase 1','is_current'=>true]);User::create(['name'=>'Administrateur PRISE','email'=>'admin@prise.local','password'=>'ChangeMe123!','role'=>'ADMIN','is_active'=>true,'can_view_archives'=>true,'can_manage_guarantees'=>true]);$c=Company::create(['project_id'=>$prise->id,'name'=>'Entreprise de démonstration']);$phase=ProjectPhase::where('project_id',$prise->id)->where('number',2)->first();$contract=Contract::create(['project_id'=>$prise->id,'phase_id'=>$phase->id,'company_id'=>$c->id,'reference'=>'DEMO-001','title'=>'Contrat de démonstration','province'=>'Kinshasa','amount'=>1000000,'initial_financing_rate'=>10,'start_date'=>now()->subMonths(2),'end_date'=>now()->addMonths(10)]);$contract->sites()->create(['province'=>'Kinshasa','work_type'=>'AEP','name'=>'Site démonstration A','description'=>'Site de démonstration']);}}
